import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Module: hnl_engine_transform","description":"","frontmatter":{},"headers":[],"relativePath":"api/engine-transform/hnl_engine_transform/hnl_engine_transform.md","filePath":"api/engine-transform/hnl_engine_transform/hnl_engine_transform.md"}`),a={name:`api/engine-transform/hnl_engine_transform/hnl_engine_transform.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p><strong>hnl_engine_transform</strong></p><h1 id="module-hnl-engine-transform" tabindex="-1">Module: hnl_engine_transform <a class="header-anchor" href="#module-hnl-engine-transform" aria-label="Permalink to “Module: hnl_engine_transform”">​</a></h1><h2 id="contents" tabindex="-1">Contents <a class="header-anchor" href="#contents" aria-label="Permalink to “Contents”">​</a></h2><p><strong>Modules</strong></p><ul><li><a href="#condition"><code>condition</code></a> - <code>TransformCondition</code> evaluation (ADR-0094 §3).</li><li><a href="#native"><code>native</code></a> - Native-rewrite seam and helper context (ADR-0094).</li><li><a href="#output"><code>output</code></a> - Output and provenance types for the transform operation (ADR-0094).</li><li><a href="#request"><code>request</code></a> - Request and mode types for the transform operation (ADR-0094).</li><li><a href="#source"><code>source</code></a> - Rule-source seam for transform engines (ADR-0094).</li><li><a href="#validate"><code>validate</code></a> - Validation for transform rule sets (ADR-0094 &quot;Production readiness&quot;).</li></ul><p><strong>Structs</strong></p><ul><li><a href="#match"><code>Match</code></a> - A single site where a transform rule would fire.</li><li><a href="#transform"><code>Transform</code></a> - The transform operation marker.</li></ul><p><strong>Traits</strong></p><ul><li><a href="#transformengine"><code>TransformEngine</code></a> - The trait a transform engine implements.</li></ul><hr><h2 id="hnl-engine-transform-match" tabindex="-1">hnl_engine_transform::Match <a class="header-anchor" href="#hnl-engine-transform-match" aria-label="Permalink to “hnl_engine_transform::Match”">​</a></h2><p><em>Struct</em></p><p>A single site where a transform rule would fire.</p><p>Returned by [<code>TransformEngine::find_matches</code>] for lint, LSP, and match-preview use cases. <code>bindings</code> maps pattern variables (role or index names) to the input <code>AstRef</code>s they matched.</p><p><strong>Fields:</strong></p><ul><li><code>at: handl_language::AstRef</code> - The input node the rule matches.</li><li><code>rule_id: String</code> - The id of the matching <a href="./handl_language::TransformDef.html"><code>TransformDef</code></a>.</li><li><code>bindings: std::collections::BTreeMap&lt;String, handl_language::AstRef&gt;</code> - Pattern bindings for the match (currently by role/index name).</li></ul><p><strong>Traits:</strong> Eq</p><p><strong>Trait Implementations:</strong></p><ul><li><strong>PartialEq</strong><ul><li><code>fn eq(self: &amp;Self, other: &amp;Self) -&gt; bool</code></li></ul></li><li><strong>Clone</strong><ul><li><code>fn clone(self: &amp;Self) -&gt; Self</code></li></ul></li><li><strong>Debug</strong><ul><li><code>fn fmt(self: &amp;Self, f: &amp; mut $crate::fmt::Formatter) -&gt; $crate::fmt::Result</code></li></ul></li></ul><h2 id="hnl-engine-transform-transform" tabindex="-1">hnl_engine_transform::Transform <a class="header-anchor" href="#hnl-engine-transform-transform" aria-label="Permalink to “hnl_engine_transform::Transform”">​</a></h2><p><em>Struct</em></p><p>The transform operation marker.</p><p>A zero-sized type identifying an AST-to-AST rewrite: it never evaluates, typechecks, or emits. It carries no state; its purpose is to namespace the transform abstraction and pair with [<code>TransformRequest</code>].</p><p><strong>Unit Struct</strong></p><p><strong>Traits:</strong> Copy, Eq</p><p><strong>Trait Implementations:</strong></p><ul><li><strong>Clone</strong><ul><li><code>fn clone(self: &amp;Self) -&gt; Self</code></li></ul></li><li><strong>Debug</strong><ul><li><code>fn fmt(self: &amp;Self, f: &amp; mut $crate::fmt::Formatter) -&gt; $crate::fmt::Result</code></li></ul></li><li><strong>Default</strong><ul><li><code>fn default() -&gt; Self</code></li></ul></li><li><strong>PartialEq</strong><ul><li><code>fn eq(self: &amp;Self, other: &amp;Self) -&gt; bool</code></li></ul></li></ul><h2 id="hnl-engine-transform-transformengine" tabindex="-1">hnl_engine_transform::TransformEngine <a class="header-anchor" href="#hnl-engine-transform-transformengine" aria-label="Permalink to “hnl_engine_transform::TransformEngine”">​</a></h2><p><em>Trait</em></p><p>The trait a transform engine implements.</p><p>An engine looks up <code>lang.transforms</code> and rewrites <code>req.ast</code> according to the requested <a href="crate::request::TransformMode" target="_blank" rel="noreferrer"><code>TransformMode</code></a>. It is pure data-driven: it does not match on a static <code>CanonicalKind</code> enum.</p><p><strong>Methods:</strong></p><ul><li><code>transform</code>: Apply the transform described by <code>req</code> to <code>req.ast</code>.</li><li><code>find_matches</code>: Match-only: find every site where a rule would fire, without rewriting.</li><li><code>box_clone</code>: Produce an owned boxed clone of this engine (ADR-0047 §2).</li><li><code>with_natives</code>: Produce a fresh owned engine with the given native-rewrite registry.</li></ul><h2 id="module-condition" tabindex="-1">Module: condition <a class="header-anchor" href="#module-condition" aria-label="Permalink to “Module: condition”">​</a></h2><p><code>TransformCondition</code> evaluation (ADR-0094 §3).</p><p>Conditions are pure predicates over the <em>input</em> node (pre-remap) and the input arena. <code>KindAt</code> resolves the child position by named role via <a href="./handl_language::AstShapeDef::role_index.html"><code>AstShapeDef::role_index</code></a> (ADR-0081), falling back to the positional <code>index</code> for shapes that declare no roles.</p><h2 id="module-native" tabindex="-1">Module: native <a class="header-anchor" href="#module-native" aria-label="Permalink to “Module: native”">​</a></h2><p>Native-rewrite seam and helper context (ADR-0094).</p><p>[<code>RewriteCtx</code>] bundles the five pieces a native rewrite needs — the [<code>Language</code>] (for role-based shape queries), the input node (pre-remap), the input arena, the output arena, and the old→new <code>remap</code> table — so a native can move existing arena-building code (e.g. the legacy <code>handl-runtime::desugar_pass</code> desugar functions) behind the [<code>NativeRewrite</code>] trait almost verbatim.</p><h2 id="module-output" tabindex="-1">Module: output <a class="header-anchor" href="#module-output" aria-label="Permalink to “Module: output”">​</a></h2><p>Output and provenance types for the transform operation (ADR-0094).</p><h2 id="module-request" tabindex="-1">Module: request <a class="header-anchor" href="#module-request" aria-label="Permalink to “Module: request”">​</a></h2><p>Request and mode types for the transform operation (ADR-0094).</p><h2 id="module-source" tabindex="-1">Module: source <a class="header-anchor" href="#module-source" aria-label="Permalink to “Module: source”">​</a></h2><p>Rule-source seam for transform engines (ADR-0094).</p><h2 id="module-validate" tabindex="-1">Module: validate <a class="header-anchor" href="#module-validate" aria-label="Permalink to “Module: validate”">​</a></h2><p>Validation for transform rule sets (ADR-0094 &quot;Production readiness&quot;).</p>`,47)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};